contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(address _owner) public {
        require(_owner != address(0));
        address initialOwner = c.owner(); if (__ESBMC_reverted()) return;
        require(initialOwner == address(this));

        bool reverted;
        bool success;
        bool _success = c.setOwner(_owner); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
            success = _success;
        }

        address finalOwner = c.owner(); if (__ESBMC_reverted()) return;
        assert(!reverted && success && finalOwner == _owner);
    }

    receive() external payable {}
}

